/**
 * Ralph Subagent Module
 *
 * Handles spawning and running subagents for dedicated tasks like PR review.
 * Subagents run sequentially - ralph waits for completion before continuing.
 */

import type { AgentAdapter } from "../agents/adapters.js";
import { spawnAndInitialize, type SpawnedAgent } from "../agents/spawner.js";
import type { SessionUpdate } from "../acp/index.js";
import { createTranslator } from "./events.js";
import { createPrefixedRenderer } from "./cli-renderer.js";

// ============================================================================
// Types
// ============================================================================

/**
 * Context provided to a subagent for its task.
 * AC: @ralph-subagent-spawning ac-10
 */
export interface SubagentContext {
  /** Task reference (e.g., @task-slug) */
  taskRef: string;
  /** Full task details from kspec task get */
  taskDetails: Record<string, unknown>;
  /** Linked spec with acceptance criteria, if spec_ref exists */
  specWithACs: Record<string, unknown> | null;
  /** Current git branch */
  gitBranch: string;
}

/**
 * Configuration for subagent execution.
 */
export interface SubagentConfig {
  /** Timeout in milliseconds (default: 20 minutes) */
  timeout: number;
  /** Output prefix for distinguishing subagent output */
  outputPrefix: string;
}

/**
 * Result of running a subagent.
 */
export interface SubagentResult {
  /** Whether the subagent completed successfully */
  success: boolean;
  /** Whether the subagent timed out */
  timedOut: boolean;
  /** Error message if failed */
  error?: string;
}

/**
 * Options for running a subagent.
 */
export interface SubagentOptions {
  /** Whether to auto-approve tool requests */
  yolo: boolean;
  /** Working directory */
  cwd: string;
  /** Tool request handler */
  handleRequest: (
    client: SpawnedAgent["client"],
    reqId: string | number,
    method: string,
    params: unknown,
  ) => Promise<void>;
}

// ============================================================================
// Default Configuration
// ============================================================================

/** Default subagent timeout: 20 minutes */
export const DEFAULT_SUBAGENT_TIMEOUT = 20 * 60 * 1000;

/** Default output prefix for subagent */
export const DEFAULT_SUBAGENT_PREFIX = "[REVIEW SUBAGENT]";

/**
 * Default ACP prompt timeout for ralph agents: 30 minutes.
 * The framing layer default (5 min) is too aggressive — API slowness,
 * extended thinking, and large context processing can exceed it even
 * with the keepalive mechanism (which resets on tool calls/notifications).
 */
export const RALPH_PROMPT_TIMEOUT = 30 * 60 * 1000;

// ============================================================================
// Prompt Builder
// ============================================================================

/**
 * Build the prompt for a PR review subagent.
 * AC: @ralph-subagent-spawning ac-2, ac-10, ac-12
 */
export function buildSubagentPrompt(context: SubagentContext): string {
  const specSection = context.specWithACs
    ? `
## Linked Spec with Acceptance Criteria

\`\`\`json
${JSON.stringify(context.specWithACs, null, 2)}
\`\`\`

**Verify all ACs have test coverage before merging.**
`
    : "";

  return `# PR Review Subagent

You are a subagent spawned by ralph to REVIEW a PR and merge it only if clean.

## Role Boundary

You are a REVIEWER, not a fixer. Your responsibilities:
- Review code quality, AC coverage (own + trait), spec alignment
- Post findings as inline PR comments with severity (MUST-FIX:, SHOULD-FIX:, SUGGESTION:)
- Merge the PR ONLY if all quality gates pass (no MUST-FIX or SHOULD-FIX items)
- Complete the task after merge

You MUST NOT:
- Fix code issues yourself
- Push commits to the PR branch
- Add or modify tests
- Make any code changes

If you find issues:
1. Post them as inline PR comments with severity prefix
2. Transition the task to needs_work: \`kspec task needs-work ${context.taskRef} --reason "findings..."\`
3. Exit — the worker agent will fix issues in the next iteration

## Context

- **Task:** \`${context.taskRef}\`
- **Branch:** \`${context.gitBranch}\`

### Task Details

\`\`\`json
${JSON.stringify(context.taskDetails, null, 2)}
\`\`\`
${specSection}
## Instructions

Run the PR review skill:

\`\`\`
/pr-review ${context.taskRef}
\`\`\`

The skill defines all review steps, quality gates, and merge criteria. Follow it completely.

Do NOT start new work. Do NOT fix code. Your only job is reviewing this task's PR, posting findings, and merging if clean.
`;
}

// ============================================================================
// Subagent Runner
// ============================================================================

/**
 * Run a subagent for a dedicated task.
 *
 * AC: @ralph-subagent-spawning ac-1 (spawn), ac-3 (sequential), ac-4 (output),
 *     ac-9 (timeout), ac-11 (prefix)
 *
 * @param adapter - Agent adapter to use for spawning
 * @param context - Task context for the subagent
 * @param config - Subagent configuration (timeout, prefix)
 * @param options - Runtime options (cwd, request handler)
 * @returns Result indicating success/failure/timeout
 */
export async function runSubagent(
  adapter: AgentAdapter,
  context: SubagentContext,
  config: SubagentConfig,
  options: SubagentOptions,
): Promise<SubagentResult> {
  const prompt = buildSubagentPrompt(context);
  let agent: SpawnedAgent | null = null;

  try {
    // AC: @ralph-subagent-spawning ac-1 - Spawn new ACP process
    agent = await spawnAndInitialize(adapter, {
      cwd: options.cwd,
      clientOptions: {
        clientInfo: {
          name: "kspec-ralph-subagent",
          version: "1.0.0",
        },
        methodTimeouts: {
          "session/prompt": RALPH_PROMPT_TIMEOUT,
          "session/resume": RALPH_PROMPT_TIMEOUT,
        },
      },
    });

    // AC: @ralph-subagent-spawning ac-4, ac-11 - Prefixed renderer for output
    const translator = createTranslator();
    const renderer = createPrefixedRenderer(config.outputPrefix);

    // Set up streaming update handler
    agent.client.on("update", (_sid: string, update: SessionUpdate) => {
      const event = translator.translate(update);
      if (event) {
        renderer.render(event);
      }
    });

    // Set up tool request handler
    agent.client.on(
      "request",
      (reqId: string | number, method: string, params: unknown) => {
        options
          .handleRequest(agent!.client, reqId, method, params)
          .catch((err) => {
            agent!.client.respondError(reqId, -32000, err.message);
          });
      },
    );

    // Create ACP session
    const acpSessionId = await agent.client.newSession({
      cwd: options.cwd,
      mcpServers: [],
    });

    // AC: @ralph-subagent-spawning ac-9 - Timeout handling
    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(
        () => reject(new Error("SUBAGENT_TIMEOUT")),
        config.timeout,
      );
    });

    // AC: @ralph-subagent-spawning ac-3 - Ralph waits for completion
    const promptPromise = agent.client.prompt({
      sessionId: acpSessionId,
      prompt: [{ type: "text", text: prompt }],
    });

    // Race between completion and timeout
    await Promise.race([promptPromise, timeoutPromise]);

    return { success: true, timedOut: false };
  } catch (err) {
    const error = err as Error;

    // AC: @ralph-subagent-spawning ac-9 - Timeout detection
    if (error.message === "SUBAGENT_TIMEOUT") {
      return { success: false, timedOut: true };
    }

    return { success: false, timedOut: false, error: error.message };
  } finally {
    // Always clean up the agent process
    if (agent) {
      agent.kill();
    }
  }
}

/**
 * Ralph command - automated task loop via ACP.
 *
 * Runs an ACP-compliant agent in a loop to process tasks autonomously.
 * Uses session event storage for full audit trail and streaming output.
 */

import { spawn, spawnSync } from "node:child_process";
import * as fs from "node:fs/promises";
import { createRequire } from "node:module";
import * as path from "node:path";
import chalk from "chalk";
import type { Command } from "commander";
import { ulid } from "ulid";

// Read version from package.json for ACP client info
const require = createRequire(import.meta.url);
const { version: packageVersion } = require("../../../package.json");

import type { ACPClient } from "../../acp/client.js";
import type {
  ReadTextFileRequest,
  RequestPermissionRequest,
  SessionUpdate,
  WriteTextFileRequest,
} from "../../acp/index.js";
import {
  type AgentAdapter,
  registerAdapter,
  resolveAdapter,
} from "../../agents/index.js";
import { type SpawnedAgent, spawnAndInitialize } from "../../agents/spawner.js";
import {
  initContext,
  type KspecContext,
  loadAllItems,
  loadAllTasks,
  type LoadedTask,
  ReferenceIndex,
} from "../../parser/index.js";
import {
  buildWrapUpContext,
  createCliRenderer,
  createTranslator,
  DEFAULT_SUBAGENT_PREFIX,
  DEFAULT_WRAPUP_TIMEOUT,
  type ExitReason,
  RALPH_PROMPT_TIMEOUT,
  runSubagent,
  runWrapUpAgent,
  type SubagentContext,
  WRAPUP_AGENT_PREFIX,
} from "../../ralph/index.js";
import {
  appendEvent,
  createSession,
  saveSessionContext,
  updateSessionStatus,
} from "../../sessions/index.js";
import { errors } from "../../strings/index.js";
import { getCurrentBranch } from "../../utils/git.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, info, success, warn } from "../output.js";
import {
  gatherSessionContext,
  getIterationStats,
  type ActiveTaskSummary,
  type SessionContext,
} from "./session.js";

// ─── Task Limit Marker ──────────────────────────────────────────────────────

/**
 * Marker file schema for task limit enforcement.
 * AC: @ralph-task-limit ac-marker-format
 */
interface TaskLimitMarker {
  active: boolean;
  since: string; // ISO8601
  max: number;
  completed: number;
  sessionId: string;
}

const TASK_LIMIT_MARKER_PATH = ".claude/ralph-task-limit.json";
const END_LOOP_MARKER_PATH = ".claude/ralph-end-loop.json";
const STALE_MARKER_THRESHOLD_MS = 60 * 60 * 1000; // 1 hour

// ─── End Loop Marker ────────────────────────────────────────────────────────

/**
 * Marker file schema for explicit end-loop signaling.
 * AC: @ralph-end-loop ac-cmd
 */
interface EndLoopMarker {
  requested: boolean;
  timestamp: string; // ISO8601
  reason?: string;
}

/**
 * Write task limit marker file.
 * AC: @ralph-task-limit ac-wrapup, ac-marker-format
 */
async function writeTaskLimitMarker(
  rootDir: string,
  marker: TaskLimitMarker,
): Promise<void> {
  const markerPath = path.join(rootDir, TASK_LIMIT_MARKER_PATH);
  const dir = path.dirname(markerPath);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(markerPath, JSON.stringify(marker, null, 2));
}

/**
 * Read task limit marker file if it exists.
 */
async function readTaskLimitMarker(
  rootDir: string,
): Promise<TaskLimitMarker | null> {
  const markerPath = path.join(rootDir, TASK_LIMIT_MARKER_PATH);
  try {
    const content = await fs.readFile(markerPath, "utf-8");
    return JSON.parse(content) as TaskLimitMarker;
  } catch {
    return null;
  }
}

/**
 * Clear task limit marker file.
 * AC: @ralph-task-limit ac-reset
 */
async function clearTaskLimitMarker(rootDir: string): Promise<void> {
  const markerPath = path.join(rootDir, TASK_LIMIT_MARKER_PATH);
  try {
    await fs.unlink(markerPath);
  } catch {
    // Ignore if file doesn't exist
  }
}

/**
 * Clear stale marker files (older than 1 hour).
 * AC: @ralph-task-limit ac-reset
 */
async function clearStaleMarker(rootDir: string): Promise<boolean> {
  const marker = await readTaskLimitMarker(rootDir);
  if (!marker) return false;

  const markerAge = Date.now() - new Date(marker.since).getTime();
  if (markerAge > STALE_MARKER_THRESHOLD_MS) {
    await clearTaskLimitMarker(rootDir);
    return true;
  }
  return false;
}

/**
 * Write end-loop marker file.
 * AC: @ralph-end-loop ac-cmd
 */
async function writeEndLoopMarker(
  rootDir: string,
  reason?: string,
): Promise<void> {
  const markerPath = path.join(rootDir, END_LOOP_MARKER_PATH);
  const dir = path.dirname(markerPath);
  await fs.mkdir(dir, { recursive: true });
  const marker: EndLoopMarker = {
    requested: true,
    timestamp: new Date().toISOString(),
    reason,
  };
  await fs.writeFile(markerPath, JSON.stringify(marker, null, 2));
}

/**
 * Read end-loop marker file if it exists.
 * AC: @ralph-end-loop ac-detect
 */
async function readEndLoopMarker(
  rootDir: string,
): Promise<EndLoopMarker | null> {
  const markerPath = path.join(rootDir, END_LOOP_MARKER_PATH);
  try {
    const content = await fs.readFile(markerPath, "utf-8");
    return JSON.parse(content) as EndLoopMarker;
  } catch {
    return null;
  }
}

/**
 * Clear end-loop marker file.
 * AC: @ralph-end-loop ac-cleanup
 */
async function clearEndLoopMarker(rootDir: string): Promise<void> {
  const markerPath = path.join(rootDir, END_LOOP_MARKER_PATH);
  try {
    await fs.unlink(markerPath);
  } catch {
    // Ignore if file doesn't exist
  }
}

/**
 * Clear stale end-loop markers (older than 1 hour).
 * AC: @ralph-end-loop ac-cleanup
 */
async function clearStaleEndLoopMarker(rootDir: string): Promise<boolean> {
  const marker = await readEndLoopMarker(rootDir);
  if (!marker) return false;

  const markerAge = Date.now() - new Date(marker.timestamp).getTime();
  if (markerAge > STALE_MARKER_THRESHOLD_MS) {
    await clearEndLoopMarker(rootDir);
    return true;
  }
  return false;
}

/**
 * Detect if a Bash command is a task complete command.
 * AC: @ralph-task-limit ac-detection
 */
function detectTaskCompleteCommand(command: string): boolean {
  // Match variations of "kspec task complete"
  // Don't match "kspec task submit" - that's just status change to pending_review
  return /\bkspec\s+task\s+complete\b/.test(command);
}

/**
 * Detect if a Bash command is an end-loop command.
 * AC: @ralph-end-loop ac-detect
 */
function detectEndLoopCommand(command: string): boolean {
  // Match "kspec ralph end-loop" with any arguments
  return /\bkspec\s+ralph\s+end-loop\b/.test(command);
}

/**
 * Extract Bash command from SessionUpdate if it's a tool_call or tool_call_update event.
 * Returns null if not a Bash tool call.
 */
function extractBashCommand(update: SessionUpdate): string | null {
  const u = update as Record<string, unknown>;

  // Check if this is a tool call event
  if (u.sessionUpdate !== "tool_call" && u.sessionUpdate !== "tool_call_update") {
    return null;
  }

  // Extract tool name - check various locations Claude Code uses
  let toolName: string | undefined;

  // Try _meta.claudeCode.toolName first (Claude Code pattern)
  const meta = u._meta as Record<string, unknown> | undefined;
  if (meta) {
    const claudeCode = meta.claudeCode as Record<string, unknown> | undefined;
    if (claudeCode?.toolName) {
      toolName = String(claudeCode.toolName);
    } else if (meta.toolName) {
      toolName = String(meta.toolName);
    }
  }

  // Fall back to name or title field
  if (!toolName && u.name) {
    toolName = String(u.name);
  }
  if (!toolName && u.title) {
    toolName = String(u.title);
  }

  // Check if it's a Bash tool (handle MCP prefix variations)
  if (!toolName) return null;
  const isBash = toolName === "Bash" || toolName.endsWith("__Bash");
  if (!isBash) return null;

  // Extract command from input
  const input = (u.rawInput || u.input || u.params) as Record<string, unknown> | undefined;
  if (!input) return null;

  const command = input.command;
  if (typeof command !== "string") return null;

  return command;
}

// ─── Explicit Task Scope ─────────────────────────────────────────────────────

/**
 * Parsed explicit task scope for --tasks flag.
 * AC: @cli-ralph ac-21
 */
interface ExplicitTaskScope {
  /** Original refs as provided by user */
  refs: string[];
  /** Resolved ULIDs for the tasks */
  ulids: string[];
}

/**
 * Parse and validate --tasks flag value.
 * Returns resolved ULIDs for the specified task refs.
 * AC: @cli-ralph ac-21
 *
 * @throws Error if any ref cannot be resolved or is not a task
 */
async function parseExplicitTasks(
  ctx: KspecContext,
  tasksArg: string,
): Promise<ExplicitTaskScope> {
  const refs = tasksArg.split(",").map((r) => r.trim()).filter(Boolean);

  if (refs.length === 0) {
    throw new Error("--tasks requires at least one task reference");
  }

  // Load tasks and items for resolution
  const tasks = await loadAllTasks(ctx);
  const items = await loadAllItems(ctx);
  const index = new ReferenceIndex(tasks, items);

  const ulids: string[] = [];

  for (const ref of refs) {
    const result = index.resolve(ref);
    if (!result.ok) {
      throw new Error(`Cannot resolve task reference: ${ref}`);
    }

    // Verify it's a task (not a spec item)
    const task = tasks.find((t) => t._ulid === result.ulid);
    if (!task) {
      throw new Error(`Reference ${ref} is not a task`);
    }

    ulids.push(result.ulid);
  }

  return { refs, ulids };
}

/**
 * Filter session context to only include tasks from explicit scope.
 * AC: @cli-ralph ac-21
 */
function filterByExplicitTasks(
  ctx: SessionContext,
  scope: ExplicitTaskScope,
): SessionContext {
  // Task refs in context are short ULIDs (variable length from shortUlid())
  // Check if the context ref is a prefix of any explicit ULID
  const matchesScope = (taskRef: string) => {
    return scope.ulids.some((ulid) => ulid.startsWith(taskRef));
  };

  return {
    ...ctx,
    active_tasks: ctx.active_tasks.filter((t) => matchesScope(t.ref)),
    pending_review_tasks: ctx.pending_review_tasks.filter((t) => matchesScope(t.ref)),
    ready_tasks: ctx.ready_tasks.filter((t) => matchesScope(t.ref)),
  };
}

/**
 * Check if all explicit tasks are completed or blocked.
 * AC: @cli-ralph ac-21
 */
async function allExplicitTasksDone(
  ctx: KspecContext,
  scope: ExplicitTaskScope,
): Promise<{ done: boolean; statuses: Map<string, string> }> {
  const tasks = await loadAllTasks(ctx);
  const statuses = new Map<string, string>();

  for (const ulid of scope.ulids) {
    const task = tasks.find((t) => t._ulid === ulid);
    if (task) {
      statuses.set(ulid.slice(0, 8), task.status);
    }
  }

  // Check if all are completed or blocked
  const done = scope.ulids.every((ulid) => {
    const status = statuses.get(ulid.slice(0, 8));
    return status === "completed" || status === "blocked";
  });

  return { done, statuses };
}

