/**
 * Ralph Subagent Module
 *
 * Handles spawning and running subagents for dedicated tasks like PR review.
 * Subagents run sequentially - ralph waits for completion before continuing.
 */

import type { AgentAdapter } from "../agents/adapters.js";
import { spawnAndInitialize, type SpawnedAgent } from "../agents/spawner.js";
import type { SessionUpdate } from "../acp/index.js";
import { createTranslator } from "./events.js";
import { createPrefixedRenderer } from "./cli-renderer.js";

// ============================================================================
// Types
// ============================================================================

/**
 * Context provided to a subagent for its task.
 * AC: @ralph-subagent-spawning ac-10
 */
export interface SubagentContext {
  /** Task reference (e.g., @task-slug) */
  taskRef: string;
  /** Full task details from kspec task get */
  taskDetails: Record<string, unknown>;
  /** Linked spec with acceptance criteria, if spec_ref exists */
  specWithACs: Record<string, unknown> | null;
  /** Current git branch */
  gitBranch: string;
}

/**
 * Configuration for subagent execution.
 */
export interface SubagentConfig {
  /** Timeout in milliseconds (default: 20 minutes) */
  timeout: number;
  /** Output prefix for distinguishing subagent output */
  outputPrefix: string;
}

/**
 * Result of running a subagent.
 */
export interface SubagentResult {
  /** Whether the subagent completed successfully */
  success: boolean;
  /** Whether the subagent timed out */
  timedOut: boolean;
  /** Error message if failed */
  error?: string;
}

/**
 * Options for running a subagent.
 */
export interface SubagentOptions {
  /** Whether to auto-approve tool requests */
  yolo: boolean;
  /** Working directory */
  cwd: string;
  /** Tool request handler */
  handleRequest: (
    client: SpawnedAgent["client"],
    reqId: string | number,
    method: string,
    params: unknown,
  ) => Promise<void>;
}

// ============================================================================
// Default Configuration
// ============================================================================

/** Default subagent timeout: 20 minutes */
export const DEFAULT_SUBAGENT_TIMEOUT = 20 * 60 * 1000;

/** Default output prefix for subagent */
export const DEFAULT_SUBAGENT_PREFIX = "[REVIEW SUBAGENT]";

/**
 * Default ACP prompt timeout for ralph agents: 30 minutes.
 * The framing layer default (5 min) is too aggressive — API slowness,
 * extended thinking, and large context processing can exceed it even
 * with the keepalive mechanism (which resets on tool calls/notifications).
 */
export const RALPH_PROMPT_TIMEOUT = 30 * 60 * 1000;

// ============================================================================
// Prompt Builder
// ============================================================================

/**
 * Build the prompt for a PR review subagent.
 * AC: @ralph-subagent-spawning ac-2, ac-10, ac-12
 */
export function buildSubagentPrompt(context: SubagentContext): string {
  const specSection = context.specWithACs
    ? `

  iteration: number,
  maxLoops: number,
  sessionId: string,
  focus?: string,
  explicitTaskScope?: ExplicitTaskScope,
): string {
  const focusSection = focus
    ? `
## Session Focus (applies to ALL iterations)

> **${focus}**

Keep this focus in mind throughout your work. It takes priority over default task selection.
`
    : "";

  // AC: @cli-ralph ac-21 - Explicit task scope indicator in prompt
  const taskScopeSection = explicitTaskScope
    ? `
## Explicit Task Scope

This session is scoped to specific tasks: ${explicitTaskScope.refs.join(", ")}

**Only work on these tasks.** The loop will exit when all listed tasks are completed or blocked.
`
    : "";

  const modeDescription = explicitTaskScope
    ? "Loop mode means: no confirmations, auto-resolve decisions, explicit task scope (only the listed tasks)."
    : "Loop mode means: no confirmations, auto-resolve decisions, automation-eligible tasks only.";

  return `# Kspec Automation Session - Task Work

**Session ID:** \`${sessionId}\`
**Iteration:** ${iteration} of ${maxLoops}
**Mode:** Automated (no human in the loop)
${focusSection}${taskScopeSection}

## Current State
\`\`\`json
${JSON.stringify(sessionCtx, null, 2)}
\`\`\`

## Instructions

Run the task-work skill in loop mode:

\`\`\`
/task-work loop
\`\`\`

${modeDescription}

**Normal flow:** Work on a task, create a PR, then stop responding. Ralph continues automatically —
it checks for remaining eligible tasks at the start of each iteration and exits the loop itself when none remain.

**Do NOT call \`end-loop\` after completing a task.** Simply stop responding.
\`end-loop\` is a rare escape hatch for when work is stalling across multiple iterations with no progress — not a normal exit path.
`;
}

/**
 * Build the reflect prompt sent after task-work completes.
 * Ralph sends this as a separate prompt to ensure reflection always happens.
 */
function buildReflectPrompt(
  iteration: number,
  maxLoops: number,
  sessionId: string,
): string {
  const isFinal = iteration === maxLoops;

  return `# Kspec Automation Session - Reflection

**Session ID:** \`${sessionId}\`
**Iteration:** ${iteration} of ${maxLoops}
**Phase:** Post-task reflection

## Instructions

Run the reflect skill in loop mode:

\`\`\`
/reflect loop
\`\`\`

Loop mode means: high-confidence captures only, must search existing before capturing, no user prompts.
${
  isFinal
    ? `
**FINAL ITERATION** - This is the last chance to capture insights from this session.
`
    : ""
}
Exit when reflection is complete.
`;
}

// ─── Streaming Output ────────────────────────────────────────────────────────

