/**
 * Ralph Subagent Module
 *
 * Handles spawning and running subagents for dedicated tasks like PR review.
 * Subagents run sequentially - ralph waits for completion before continuing.
 */

import type { AgentAdapter } from "../agents/adapters.js";
import { spawnAndInitialize, type SpawnedAgent } from "../agents/spawner.js";
import type { SessionUpdate } from "../acp/index.js";
import { createTranslator } from "./events.js";
import { createPrefixedRenderer } from "./cli-renderer.js";

// ============================================================================
// Types
// ============================================================================

/**
 * Context provided to a subagent for its task.
 * AC: @ralph-subagent-spawning ac-10
 */
export interface SubagentContext {
  /** Task reference (e.g., @task-slug) */
  taskRef: string;
  /** Full task details from kspec task get */
  taskDetails: Record<string, unknown>;
  /** Linked spec with acceptance criteria, if spec_ref exists */
  specWithACs: Record<string, unknown> | null;
  /** Current git branch */
  gitBranch: string;
}

/**
 * Configuration for subagent execution.
 */
export interface SubagentConfig {
  /** Timeout in milliseconds (default: 20 minutes) */
  timeout: number;
  /** Output prefix for distinguishing subagent output */
  outputPrefix: string;
}

/**
 * Result of running a subagent.
 */
export interface SubagentResult {
  /** Whether the subagent completed successfully */
  success: boolean;
  /** Whether the subagent timed out */
  timedOut: boolean;
  /** Error message if failed */
  error?: string;
}

/**
 * Options for running a subagent.
 */
export interface SubagentOptions {
  /** Whether to auto-approve tool requests */
  yolo: boolean;
  /** Working directory */
  cwd: string;
  /** Tool request handler */
  handleRequest: (
    client: SpawnedAgent["client"],
    reqId: string | number,
    method: string,
    params: unknown,
  ) => Promise<void>;
}

// ============================================================================
// Default Configuration
// ============================================================================

/** Default subagent timeout: 20 minutes */
export const DEFAULT_SUBAGENT_TIMEOUT = 20 * 60 * 1000;

/** Default output prefix for subagent */
export const DEFAULT_SUBAGENT_PREFIX = "[REVIEW SUBAGENT]";

// ============================================================================
// Skill Invocation Names
// ============================================================================
// Ralph prompts reference skills by invocation name. These are defined as
// constants so they're easy to update as core skills are created under the
// kspec: namespace. Projects can also override these via meta configuration
// in the future.

/** Skill invocation for task-work in ralph worker prompt */
export const SKILL_TASK_WORK = "/task-work";

/** Skill invocation for reflect in ralph reflect prompt */
export const SKILL_REFLECT = "/reflect";

/** Skill invocation for PR review in ralph subagent prompt */
export const SKILL_PR_REVIEW = "/pr-review";

/**
 * Default ACP prompt timeout for ralph agents: 30 minutes.
 * The framing layer default (5 min) is too aggressive — API slowness,
 * extended thinking, and large context processing can exceed it even
 * with the keepalive mechanism (which resets on tool calls/notifications).
 */
export const RALPH_PROMPT_TIMEOUT = 30 * 60 * 1000;

// ============================================================================
// Prompt Builder
// ============================================================================

/**
 * Build the prompt for a PR review subagent.
 * AC: @ralph-subagent-spawning ac-2, ac-10, ac-12
 */
export function buildSubagentPrompt(context: SubagentContext): string {
  const specSection = context.specWithACs
    ? `
## Linked Spec with Acceptance Criteria

\`\`\`json
${JSON.stringify(context.specWithACs, null, 2)}
\`\`\`

**Verify all ACs have test coverage before merging.**
`
    : "";

  return `# PR Review Subagent

You are a subagent spawned by ralph to REVIEW a PR and merge it only if clean.

## Role Boundary

You are a REVIEWER, not a fixer. Your responsibilities:
- Review code quality, AC coverage (own + trait), spec alignment
- Post findings as inline PR comments with severity (MUST-FIX:, SHOULD-FIX:, SUGGESTION:)
- Merge the PR ONLY if all quality gates pass (no MUST-FIX or SHOULD-FIX items)
- Complete the task after merge

You MUST NOT:
- Fix code issues yourself
- Push commits to the PR branch
- Add or modify tests
- Make any code changes

If you find issues:
1. Post them as inline PR comments with severity prefix
2. Transition the task to needs_work: \`kspec task needs-work ${context.taskRef} --reason "findings..."\`
3. Exit — the worker agent will fix issues in the next iteration

## Context

- **Task:** \`${context.taskRef}\`
- **Branch:** \`${context.gitBranch}\`

### Task Details

\`\`\`json
${JSON.stringify(context.taskDetails, null, 2)}
\`\`\`
${specSection}
## Instructions

Run the PR review skill:

\`\`\`
${SKILL_PR_REVIEW} ${context.taskRef}
\`\`\`

The skill defines all review steps, quality gates, and merge criteria. Follow it completely.

Do NOT start new work. Do NOT fix code. Your only job is reviewing this task's PR, posting findings, and merging if clean.
`;
}

// ============================================================================
// Subagent Runner
// ============================================================================

/**
 * Run a subagent for a dedicated task.
 *
 * AC: @ralph-subagent-spawning ac-1 (spawn), ac-3 (sequential), ac-4 (output),
 *     ac-9 (timeout), ac-11 (prefix)
 *
 * @param adapter - Agent adapter to use for spawning
 * @param context - Task context for the subagent
 * @param config - Subagent configuration (timeout, prefix)
 * @param options - Runtime options (cwd, request handler)
 * @returns Result indicating success/failure/timeout
 */
export async function runSubagent(
  adapter: AgentAdapter,
  context: SubagentContext,
  config: SubagentConfig,
  options: SubagentOptions,
): Promise<SubagentResult> {
  const prompt = buildSubagentPrompt(context);
  let agent: SpawnedAgent | null = null;

  try {
    // AC: @ralph-subagent-spawning ac-1 - Spawn new ACP process
    agent = await spawnAndInitialize(adapter, {
      cwd: options.cwd,
      clientOptions: {
        clientInfo: {
          name: "kspec-ralph-subagent",
          version: "1.0.0",
        },
        methodTimeouts: {
          "session/prompt": RALPH_PROMPT_TIMEOUT,
          "session/resume": RALPH_PROMPT_TIMEOUT,
        },
      },
    });

    // AC: @ralph-subagent-spawning ac-4, ac-11 - Prefixed renderer for output
    const translator = createTranslator();
    const renderer = createPrefixedRenderer(config.outputPrefix);

    // Set up streaming update handler
    agent.client.on("update", (_sid: string, update: SessionUpdate) => {
      const event = translator.translate(update);
      if (event) {
        renderer.render(event);
      }
    });

    // Set up tool request handler
    agent.client.on(
      "request",
      (reqId: string | number, method: string, params: unknown) => {
        options
          .handleRequest(agent!.client, reqId, method, params)
          .catch((err) => {
            agent!.client.respondError(reqId, -32000, err.message);
          });
      },
    );

    // Create ACP session
    const acpSessionId = await agent.client.newSession({
      cwd: options.cwd,
      mcpServers: [],
    });

    // AC: @ralph-subagent-spawning ac-9 - Timeout handling
    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(
        () => reject(new Error("SUBAGENT_TIMEOUT")),
        config.timeout,
      );
    });

    // AC: @ralph-subagent-spawning ac-3 - Ralph waits for completion
    const promptPromise = agent.client.prompt({
      sessionId: acpSessionId,
      prompt: [{ type: "text", text: prompt }],
    });

    // Race between completion and timeout
    await Promise.race([promptPromise, timeoutPromise]);

    return { success: true, timedOut: false };
  } catch (err) {
    const error = err as Error;

    // AC: @ralph-subagent-spawning ac-9 - Timeout detection
    if (error.message === "SUBAGENT_TIMEOUT") {
      return { success: false, timedOut: true };
    }

    return { success: false, timedOut: false, error: error.message };
  } finally {
    // Always clean up the agent process
    if (agent) {
      agent.kill();
    }
  }
}

/**
 * Project-level configuration for kspec.
 *
 * Loads kspec.config.yaml from the project root (main branch) before shadow
 * branch detection. All fields are optional with backward-compatible defaults.
 *
 * Priority: env vars > config file > defaults
 *
 * @module
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { z } from "zod";
import * as YAML from "yaml";
import { getGitRoot } from "./shadow.js";

// ── Schema ──────────────────────────────────────────────────────────────

/**
 * Schema for shadow branch configuration.
 *
 * AC: @config-shadow — shadow.branch, shadow.directory, shadow.remote configurable
 */
const ShadowConfigSchema = z
  .object({
    /** Branch name for shadow branch (default: kspec-meta) */
    branch: z.string().optional(),
    /** Worktree directory name (default: .kspec) */
    directory: z.string().optional(),
    /**
     * Remote target for shadow branch. Can be:
     * - Named remote (e.g., "origin", "specs-origin")
     * - Local filesystem path (starts with /, ./, or ~)
     * - Git URL (contains :// or starts with git@)
     */
    remote: z.string().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for identity configuration.
 */
const IdentityConfigSchema = z
  .object({
    /** Default author for notes/tasks (overridden by KSPEC_AUTHOR env var) */
    author: z.string().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for validation configuration.
 *
 * AC: @config-validation — validation settings configurable in kspec.config.yaml
 */
const ValidationConfigSchema = z
  .object({
    /**
     * When true, dangling references are treated as errors instead of warnings.
     * AC: @config-validation ac-2 ac-3 — strict_refs configurable
     */
    strict_refs: z.boolean().optional(),
    /**
     * When true, specs missing acceptance criteria are reported as errors not warnings.
     * AC: @config-validation ac-1 — require_acceptance configurable
     */
    require_acceptance: z.boolean().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for daemon configuration.
 *
 * AC: @config-daemon — daemon.port, daemon.auto_start configurable
 */
const DaemonConfigSchema = z
  .object({
    /** Default port for daemon (default: 3456) */
    port: z.number().int().min(1).max(65535).optional(),
    /** Host to bind to (default: localhost) */
    host: z.string().optional(),
    /**
     * Whether to auto-start daemon when running kspec commands.
     * AC: @config-daemon ac-3 — auto_start configurable
     */
    auto_start: z.boolean().optional(),
  })
  .strict()
  .optional();

/**
 * Complete schema for kspec.config.yaml.
 *
 * AC: @project-config ac-4 — unknown fields are ignored via passthrough
 */
export const KspecConfigSchema = z
  .object({
    /** Shadow branch configuration */
    shadow: ShadowConfigSchema,
    /** Identity configuration */
    identity: IdentityConfigSchema,
    /** Validation configuration */
    validation: ValidationConfigSchema,
    /** Daemon configuration */
    daemon: DaemonConfigSchema,
  })
  .passthrough(); // AC: ac-4 — ignore unknown fields

/**
 * Raw config type as parsed from YAML file.
 */
export type KspecConfig = z.infer<typeof KspecConfigSchema>;

/**
 * Remote type for shadow branch configuration.
 * - "named": Git remote name (e.g., "origin", "specs-origin")
 * - "path": Local filesystem path
 * - "url": Git URL (https://, git@, etc.)
 */
export type ShadowRemoteType = "named" | "path" | "url";

/**
 * Resolved shadow remote configuration.
 */
export interface ResolvedShadowRemote {
  /** The remote value from config */
  value: string;
  /** Detected type of the remote */
  type: ShadowRemoteType;
}

/**
 * Detect the type of a shadow remote string.
 *
 * AC: @config-shadow ac-3 ac-4 ac-5 — remote type detection
 *
 * @param remote Remote string from config
 * @returns Detected type: "path" for filesystem, "url" for git URLs, "named" for git remote names
 */
export function detectRemoteType(remote: string): ShadowRemoteType {
  // AC: ac-4 — Local filesystem path (starts with /, ./, ../, or ~)
  if (
    remote.startsWith("/") ||
    remote.startsWith("./") ||
    remote.startsWith("../") ||
    remote.startsWith("~")
  ) {
    return "path";
  }
  // AC: ac-5 — Git URL (contains :// or starts with git@)
  if (remote.includes("://") || remote.startsWith("git@")) {
    return "url";
  }
  // AC: ac-3 — Otherwise it's a named remote
  return "named";
}

/**
 * Resolved config with all values finalized (env vars applied, defaults filled).
 */
export interface ResolvedKspecConfig {
  shadow: {
    /** Branch name (default: kspec-meta) */
    branch: string;
    /** Worktree directory name (default: .kspec) */
    directory: string;
    /** Remote configuration, null if not specified */
    remote: ResolvedShadowRemote | null;
  };
  identity: {
    author: string | null;
  };
  validation: {
    /**
     * When true, dangling references are treated as errors instead of warnings.
     * AC: @config-validation ac-2 ac-3
     */
    strict_refs: boolean;
    /**
     * When true, specs missing acceptance criteria are reported as errors not warnings.
     * AC: @config-validation ac-1
     */
    require_acceptance: boolean;
  };
  daemon: {
    port: number;
    host: string;
    /**
     * Whether to auto-start daemon when running kspec commands.
     * AC: @config-daemon ac-3
     */
    auto_start: boolean;
  };
}

// ── Defaults ────────────────────────────────────────────────────────────

/**
 * Default configuration values.
 *
 * AC: @project-config ac-1 — these are the current defaults
 */
const DEFAULT_CONFIG: ResolvedKspecConfig = {
  shadow: {
    branch: "kspec-meta",
    directory: ".kspec",
    remote: null,
  },
  identity: {
    author: null,
  },
  validation: {
    // AC: @config-validation — defaults preserve existing behavior
    // strict_refs: true = dangling refs are errors (existing behavior)
    // require_acceptance: false = missing AC is warning (existing behavior)
    strict_refs: true,
    require_acceptance: false,
  },
  daemon: {
    port: 3456,
    host: "localhost",
    auto_start: true, // AC: @config-daemon — default auto-start enabled
  },
};

// ── Loading ─────────────────────────────────────────────────────────────

const CONFIG_FILENAME = "kspec.config.yaml";

/**
 * Result of loading project config.
 */
export interface LoadConfigResult {
  /** Resolved configuration with all values finalized */
  config: ResolvedKspecConfig;
  /** Path to config file if found, null otherwise */
  configPath: string | null;
  /** Warning message if config had issues but was recoverable */
  warning: string | null;
  /** The git root directory where config was loaded from */
  gitRoot: string | null;
}

/**
 * Find git root directory, handling KSPEC_SPEC_DIR batch mode.
 *
 * AC: @project-config ac-7 — in batch mode, we need the REAL project root
 *
 * When KSPEC_SPEC_DIR is set (batch atomic mode), the cwd might be the temp
 * directory. We need to find the real project root by checking:
 * 1. If KSPEC_BATCH_PROJECT_ROOT is set, use that (set by batch executor)
 * 2. Otherwise, use git root from cwd
 *
 * AC: @project-config ac-6 — loads from git root, not cwd subdirectory
 */
export function findProjectRoot(startDir: string): string | null {
  // In batch mode, the batch executor should set this to the real root
  // before redirecting KSPEC_SPEC_DIR
  const batchRoot = process.env.KSPEC_BATCH_PROJECT_ROOT;
  if (batchRoot) {
    return batchRoot;
  }

  // Normal mode: find git root
  return getGitRoot(startDir);
}

/**
 * Load project configuration from kspec.config.yaml.
 *
 * AC: @project-config ac-1 — no config = all defaults
 * AC: @project-config ac-2 — config parsed and available before shadow detection
 * AC: @project-config ac-3 — invalid YAML = defaults + warning
 * AC: @project-config ac-4 — unknown fields ignored
 * AC: @project-config ac-5 — env vars take precedence
 * AC: @project-config ac-6 — loads from git root
 * AC: @project-config ac-7 — batch mode uses real project root
 *
 * @param startDir Starting directory for git root detection
 */
export async function loadProjectConfig(
  startDir: string = process.cwd(),
): Promise<LoadConfigResult> {
  const gitRoot = findProjectRoot(startDir);

  if (!gitRoot) {
    // Not in a git repo, use defaults
    return {
      config: resolveConfig(null),
      configPath: null,
      warning: null,
      gitRoot: null,
    };
  }

  const configPath = path.join(gitRoot, CONFIG_FILENAME);

  // Check if config file exists
  try {
    await fs.access(configPath);
  } catch {
    // AC: ac-1 — no config file, use defaults
    return {
      config: resolveConfig(null),
      configPath: null,
      warning: null,
      gitRoot,
    };
  }

  // Try to load and parse config
  try {
    const content = await fs.readFile(configPath, "utf-8");
    const raw = YAML.parse(content);

    // Validate against schema
    const result = KspecConfigSchema.safeParse(raw);

    if (!result.success) {
      // AC: ac-3 — validation error = defaults + warning
      const issues = result.error.issues
        .map((i) => `${i.path.join(".")}: ${i.message}`)
        .join("; ");
      return {
        config: resolveConfig(null),
        configPath,
        warning: `Config validation failed: ${issues}. Using defaults.`,
        gitRoot,
      };
    }

    // AC: ac-5 — apply env var overrides during resolution
    return {
      config: resolveConfig(result.data),
      configPath,
      warning: null,
      gitRoot,
    };
  } catch (err) {
    // AC: ac-3 — parse error = defaults + warning
    const message = err instanceof Error ? err.message : String(err);
    return {
      config: resolveConfig(null),
      configPath,
      warning: `Failed to parse ${CONFIG_FILENAME}: ${message}. Using defaults.`,
      gitRoot,
    };
  }
}

/**
 * Resolve configuration by merging file config with env vars and defaults.
 *
 * Priority: env vars > config file > defaults
 *
 * AC: @project-config ac-5 — env vars take precedence
 */
export function resolveConfig(fileConfig: KspecConfig | null): ResolvedKspecConfig {
  const file = fileConfig || {};

  // Get env var overrides
  const envAuthor = process.env.KSPEC_AUTHOR;
  const envPort = process.env.KSPEC_DAEMON_PORT
    ? parseInt(process.env.KSPEC_DAEMON_PORT, 10)
    : undefined;
  const envHost = process.env.KSPEC_DAEMON_HOST;

  // Resolve shadow remote if specified
  const remoteValue = file.shadow?.remote;
  const resolvedRemote: ResolvedShadowRemote | null = remoteValue
    ? { value: remoteValue, type: detectRemoteType(remoteValue) }
    : DEFAULT_CONFIG.shadow.remote;

  return {
    shadow: {
      branch: file.shadow?.branch ?? DEFAULT_CONFIG.shadow.branch,
      directory: file.shadow?.directory ?? DEFAULT_CONFIG.shadow.directory,
      remote: resolvedRemote,
    },
    identity: {
      // AC: ac-5 — env var takes precedence
      author: envAuthor ?? file.identity?.author ?? DEFAULT_CONFIG.identity.author,
    },
    validation: {
      // AC: @config-validation ac-2 ac-3 — strict_refs from config
      strict_refs:
        file.validation?.strict_refs ?? DEFAULT_CONFIG.validation.strict_refs,
      // AC: @config-validation ac-1 — require_acceptance from config
      require_acceptance:
        file.validation?.require_acceptance ?? DEFAULT_CONFIG.validation.require_acceptance,
    },
    daemon: {
      // AC: ac-5 — env vars take precedence
      port:
        (envPort && !isNaN(envPort) ? envPort : undefined) ??
        file.daemon?.port ??
        DEFAULT_CONFIG.daemon.port,
      // AC: @config-daemon ac-5 ac-6 — host from config/env
      host: envHost ?? file.daemon?.host ?? DEFAULT_CONFIG.daemon.host,
      // AC: @config-daemon ac-3 — auto_start from config
      auto_start: file.daemon?.auto_start ?? DEFAULT_CONFIG.daemon.auto_start,
    },
  };
}

/**
 * Get the default configuration (no file, no env vars).
 * Useful for testing or when config loading fails completely.
 * Returns a deep copy to prevent mutation of shared defaults.
 */
export function getDefaultConfig(): ResolvedKspecConfig {
  return {
    shadow: {
      branch: DEFAULT_CONFIG.shadow.branch,
      directory: DEFAULT_CONFIG.shadow.directory,
      remote: DEFAULT_CONFIG.shadow.remote,
    },
    identity: { ...DEFAULT_CONFIG.identity },
    validation: {
      strict_refs: DEFAULT_CONFIG.validation.strict_refs,
      require_acceptance: DEFAULT_CONFIG.validation.require_acceptance,
    },
    daemon: {
      port: DEFAULT_CONFIG.daemon.port,
      host: DEFAULT_CONFIG.daemon.host,
      auto_start: DEFAULT_CONFIG.daemon.auto_start,
    },
  };
}

/**
 * Meta manifest loading and operations.
 *
 * The meta manifest (kynetic.meta.yaml) contains process definitions:
 * - Agents: roles, capabilities, conventions
 * - Workflows: structured processes with steps
 * - Conventions: project rules and standards
 * - Observations: feedback about processes
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { ulid } from "ulid";
import {
  type Agent,
  AgentSchema,
  type Convention,
  ConventionSchema,
  getMetaItemType,
  isSkill,
  type MetaItem,
  type MetaManifest,
  MetaManifestSchema,
  type Observation,
  ObservationSchema,
  type ObservationType,
  type SessionContext,
  SessionContextSchema,
  type Skill,
  SkillSchema,
  type Workflow,
  type WorkflowRun,
  type WorkflowRunsFile,
  WorkflowRunsFileSchema,
  WorkflowSchema,
} from "../schema/index.js";
import type { KspecContext } from "./yaml.js";
import {
  expandIncludePattern,
  getAuthor,
  readYamlFile,
  writeYamlFilePreserveFormat,
} from "./yaml.js";

/**
 * Loaded agent with runtime metadata
 */
export interface LoadedAgent extends Agent {
  _sourceFile?: string;
}

/**
 * Loaded workflow with runtime metadata
 */
export interface LoadedWorkflow extends Workflow {
  _sourceFile?: string;
}

/**
 * Loaded convention with runtime metadata
 */
export interface LoadedConvention extends Convention {
  _sourceFile?: string;
}

/**
 * Loaded observation with runtime metadata
 */
export interface LoadedObservation extends Observation {
  _sourceFile?: string;
}

/**
 * Loaded skill with runtime metadata
 */
export interface LoadedSkill extends Skill {
  _sourceFile?: string;
}

/**
 * Any loaded meta item
 */
export type LoadedMetaItem =
  | LoadedAgent
  | LoadedWorkflow
  | LoadedConvention
  | LoadedObservation
  | LoadedSkill;

/**
 * Meta context containing all loaded meta items
 */
export interface MetaContext {
  manifest: MetaManifest | null;
  manifestPath: string | null;
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
  skills: LoadedSkill[];
}

/**
 * Find the meta manifest file.
 *
 * Discovery algorithm:
 * 1. Check for explicit name: kynetic.meta.yaml (backward compat)
 * 2. If not found, scan directory for *.meta.yaml files
 * 3. For each candidate, validate it contains a 'kynetic_meta:' version field
 * 4. Return first valid match (alphabetically after explicit name)
 *
 * AC: @meta-manifest-discovery ac-1, ac-2, ac-3
 */
export async function findMetaManifest(
  specDir: string,
): Promise<string | null> {
  // AC: @meta-manifest-discovery ac-1, ac-3 - explicit name has priority
  const priorityPath = path.join(specDir, "kynetic.meta.yaml");
  try {
    await fs.access(priorityPath);
    return priorityPath;
  } catch {
    // Continue to glob fallback
  }

  // AC: @meta-manifest-discovery ac-2, ac-3 - glob fallback with validation
  try {
    const entries = await fs.readdir(specDir);
    // AC: @meta-manifest-discovery ac-3 - alphabetical order
    const candidates = entries
      .filter((f) => f.endsWith(".meta.yaml"))
      .sort();

    for (const candidate of candidates) {
      const filePath = path.join(specDir, candidate);
      try {
        const raw = await readYamlFile<unknown>(filePath);
        // AC: @meta-manifest-discovery ac-2 - validate kynetic_meta version field
        if (raw && typeof raw === "object" && "kynetic_meta" in raw) {
          return filePath;
        }
      } catch {
        // Skip invalid files
      }
    }
  } catch {
    // Directory read failed
  }

  return null;

