      const context: SubagentContext = {
        taskRef: '@task-example',
        taskDetails: { title: 'Test Task' },
        specWithACs: null,
        gitBranch: 'main',
      };

      const prompt = buildSubagentPrompt(context);

      expect(prompt).not.toContain('Linked Spec with Acceptance Criteria');
    });

