    delete process.env.KSPEC_AUTHOR;
    delete process.env.KSPEC_DAEMON_PORT;
    delete process.env.KSPEC_DAEMON_HOST;
    delete process.env.KSPEC_BATCH_PROJECT_ROOT;
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
    // Restore env
    process.env = originalEnv;
  });

