   285→    "## Quick Reference",
   286→    "- `kspec tasks ready` — see available work",
   287→    "- `kspec task start @ref` — begin a task",
   288→    '- `kspec task note @ref "..."` — add context while working',
   289→    "- `kspec setup --status` — check environment health",
   290→    "",
   291→  );
   292→
   293→  return lines.join("\n");
   294→}
   295→
   296→/**
   297→ * Get the project name from the kspec manifest, falling back to directory name.
   298→ */
   299→async function getProjectName(projectDir: string): Promise<string> {
   300→  try {
   301→    const { initContext } = await import("../../parser/index.js");
   302→    const ctx = await initContext(projectDir);
   303→    if (ctx.manifest?.project?.name) {
   304→      return ctx.manifest.project.name;
   305→    }
   306→  } catch (err) {
   307→    debugLog("Could not load manifest for project name", err);
   308→  }
   309→  return path.basename(projectDir);
   310→}
   311→
   312→/**
   313→ * Get module names from the .kspec/modules/ directory.
   314→ */
   315→async function getModuleNames(projectDir: string): Promise<string[]> {
   316→  const modulesDir = path.join(projectDir, ".kspec", "modules");
   317→  try {
   318→    const entries = await fs.readdir(modulesDir, { withFileTypes: true });
   319→    return entries
   320→      .filter((e) => e.isDirectory())
   321→      .map((e) => e.name)
   322→      .sort();
   323→  } catch (err) {
   324→    debugLog("Could not read modules directory", err);
   325→    return [];
   326→  }
   327→}
   328→
   329→/**
   330→ * Seed project memory for the detected agent platform.
   331→ *
   332→ * AC: @new-project-bootstrapping ac-2
   333→ * - Generates platform-agnostic content, delegates to platform writer
   334→ * - Currently supports Claude Code; other platforms return no-op
   335→ * - Skips if memory file already exists (unless force)
   336→ * - Creates parent directories
   337→ * - Dry-run support
   338→ */
   339→export async function seedMemory(
   340→  projectDir: string,
   341→  agentType: AgentType,
   342→  options: { dryRun?: boolean; force?: boolean } = {},
   343→): Promise<SeedResult> {
   344→  const { dryRun = false, force = false } = options;
   345→
   346→  const writer = getMemoryWriter(agentType);
   347→  if (!writer) {
   348→    return {
   349→      seeded: false,
   350→      path: "",
   351→      message: `no memory writer for ${agentType}`,
   352→    };
   353→  }
   354→
   355→  const memoryPath = writer.getMemoryPath(projectDir);
   356→
   357→  try {
   358→    // Skip if already exists (unless force)
   359→    if (!force && (await writer.exists(projectDir))) {
   360→      return {
   361→        seeded: false,
   362→        path: memoryPath,
   363→        message: "memory file already exists",
   364→      };
   365→    }
   366→
   367→    const content = await generateProjectSeedContent(projectDir);
   368→    const result = await writer.write(projectDir, content, dryRun);
   369→
   370→    return {
   371→      seeded: result.created,
   372→      path: result.path,
   373→      message: result.created ? "seeded" : "skipped",
   374→    };
   375→  } catch (err) {
   376→    debugLog("seedMemory failed", err);
   377→    return {
   378→      seeded: false,
   379→      path: memoryPath,
   380→      message: `failed: ${err instanceof Error ? err.message : String(err)}`,
   381→    };
   382→  }
   383→}
   384→
