/**
 * Status of the setup state
 * AC: @enhanced-setup ac-7, ac-8 - status reporting
 */
interface SetupStatus {
  agent: {
    detected: AgentType;
    confidence: "high" | "medium" | "low";
  };
  hooks: {
    promptCheck: boolean;
    stop: boolean;
    preToolUse: boolean;
    guardsPresent: string[];
  };
  skills: {
    total: number;
    rendered: number;
    drifted: number;
  };
