/**
 * Compare two directory trees recursively for equality.
 * Returns true if all files have identical content and structure matches.
 */
async function dirsEqual(src: string, dest: string): Promise<boolean> {
  let srcEntries: Awaited<ReturnType<typeof fs.readdir>>;
  let destEntries: Awaited<ReturnType<typeof fs.readdir>>;
  try {
    srcEntries = await fs.readdir(src, { withFileTypes: true });
    destEntries = await fs.readdir(dest, { withFileTypes: true });
  } catch {
    return false;
  }

  if (srcEntries.length !== destEntries.length) return false;

  const destMap = new Map(destEntries.map((e) => [e.name, e]));

  for (const srcEntry of srcEntries) {
    const destEntry = destMap.get(srcEntry.name);
    if (!destEntry) return false;

    const srcPath = path.join(src, srcEntry.name);
    const destPath = path.join(dest, srcEntry.name);

    if (srcEntry.isDirectory() && destEntry.isDirectory()) {
      if (!(await dirsEqual(srcPath, destPath))) return false;
    } else if (srcEntry.isFile() && destEntry.isFile()) {
      const srcContent = await fs.readFile(srcPath, "utf-8");
      const destContent = await fs.readFile(destPath, "utf-8");
      if (srcContent !== destContent) return false;
    } else {
      return false; // Type mismatch
    }
  }
  return true;
}

